  `id` int(11) NOT NULL COMMENT 'ID mẫu hợp thể (1-999: Ko item, 1000+: ID theo Item)',
  `name` varchar(255) NOT NULL,
  `fusion_type` tinyint(4) NOT NULL DEFAULT 6,
  `data_0` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Ngoại hình Trái Đất' CHECK (json_valid(`data_0`)),
  `data_1` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Ngoại hình Namek' CHECK (json_valid(`data_1`)),
  `data_2` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Ngoại hình Xayda' CHECK (json_valid(`data_2`)),
  `hp_percent` tinyint(4) DEFAULT 0,
  `mp_percent` tinyint(4) DEFAULT 0,
  `dame_percent` tinyint(4) DEFAULT 0,
  `crit_bonus` tinyint(4) DEFAULT 0,
  `is_permanent` tinyint(1) DEFAULT 1 COMMENT 'TRUE: Bông tai, FALSE: Lưỡng long/Có thời hạn',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
