(837,7476,3,120,0,34,'[{\"head\":1, \"body\":1, \"leg\":1, \"bag\":-1}]','Thẻ Lính độc nhãn','Người ta nuôi quân lính dùng trong 1 giờ, Lính độc nhãn thì không dùng được 5 phút','[{\"id\": 6, \"param\": 10000, \"activeCard\": 0},\n{\"id\": 6, \"param\": 20000, \"activeCard\": 1},\n{\"id\": 6, \"param\": 30000, \"activeCard\": 2}]',-1,0,-1),
(838,7477,3,120,0,35,'[{\"head\":1, \"body\":1, \"leg\":1, \"bag\":-1}]','Thẻ lính độc nhãn','Người ta nuôi quân lính dùng trong 1 giờ, Lính độc nhãn thì không dùng được 5 phút','[{\"id\":7,\"param\": 10000,\"activeCard\":0},{\"id\":7,\"param\": 20000,\"activeCard\":1},{\"id\":7,\"param\": 30000,\"activeCard\":2}]',-1,0,-1),
(839,7478,3,120,0,36,'[{\"head\":1, \"body\":1, \"leg\":1, \"bag\":-1}]','Thẻ sói xám','Được lính độc nhãn thuần hóa và cho giữ nhà như cún con, sở thích của chúng là được chơi trò nhặt bóng','[{\"id\":0,\"param\":500,\"activeCard\":0},{\"id\":0,\"param\":700,\"activeCard\":1},{\"id\":0,\"param\":900,\"activeCard\":2}]',-1,0,-1),
(840,7480,4,120,1,1,'[{\"head\":141, \"body\":142, \"leg\":143, \"bag\":-1}]','Thẻ trung úy trắng','Thân hình hơi béo so với tiêu chuẩn chung, luôn đeo chiếc khăn quàng đỏ, thường hay mơ mộng làm thơ','[{\"id\": 94, \"param\": 5, \"activeCard\": 0},\r\n{\"id\": 77, \"param\": 5, \"activeCard\": 1},\r\n{\"id\": 103, \"param\": 5, \"activeCard\": 2}]',-1,0,-1),
(841,7481,4,120,1,1,'[{\"head\":123, \"body\":124, \"leg\":125, \"bag\":-1}]','Thẻ ninja tím','Ninja với nhiều tài năng để trở thành sát thủ, nhưng kỹ thuật ẩn thân lại không có, nên không thể trở thành sát thủ','[{\"id\": 94, \"param\": 5, \"activeCard\": 0},\r\n{\"id\": 77, \"param\": 5, \"activeCard\": 1},\r\n{\"id\": 103, \"param\": 5, \"activeCard\": 2}]',-1,0,-1),
(842,7479,4,120,1,1,'[{\"head\":135, \"body\":136, \"leg\":137, \"bag\":-1}]','Thẻ trung úy xanh lơ','Có siêu năng lực thôi miên nhưng cực kỳ sợ chuột','[{\"id\": 94, \"param\": 5, \"activeCard\": 0},\r\n{\"id\": 77, \"param\": 5, \"activeCard\": 1},\r\n{\"id\": 103, \"param\": 5, \"activeCard\": 2}]',-1,0,-1),
(859,1568,4,120,1,1,'[{\"head\":144, \"body\":145, \"leg\":146, \"bag\":-1}]','Thẻ Độc Nhãn','Đầu não của Red Ribbon. Bị chột một mắt, Lúc nhỏ bị mọi người chê là \'thằng lùn\'','[{\"id\": 94, \"param\": 5, \"activeCard\": 0},\r\n{\"id\": 77, \"param\": 5, \"activeCard\": 1},\r\n{\"id\": 103, \"param\": 5, \"activeCard\": 2}]',-1,0,-1),
(956,8935,4,120,1,1,'[{\"head\":994, \"body\":995, \"leg\":996, \"bag\":-1}]','Thẻ Đội Trưởng Vàng','Đội trưởng vàng là 1 con hổ hình người chắc nịch cơ thể được bao phủ bởi bộ lông vàng, Goku đã đấm hắn ra khỏi máy bay của mình khi đang bay ở giữa không trung.','[{\"id\": 94, \"param\": 5, \"activeCard\": 0},\r\n{\"id\": 77, \"param\": 5, \"activeCard\": 1},\r\n{\"id\": 103, \"param\": 5, \"activeCard\": 2}]',-1,0,0);
